// The OpenCV operations reimplemented in imageOps.ts, against reference outputs
// generated by cv2 (make_opencv_cases.py). Colour and masks must be exact.
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import {
  fillPolyMask, gaussianBlurAt, laplacianAt, maskPixels, reflect101, rgbToLab8, toGray,
  type Polygon,
} from '../src/core/imageOps'

const cases = JSON.parse(readFileSync(new URL('./opencv_cases.json', import.meta.url), 'utf8'))

describe('colour conversion (bit-exact with OpenCV 8-bit)', () => {
  const { rgb, lab, gray } = cases.colors as { rgb: number[][]; lab: number[][]; gray: number[] }

  it('BGR2LAB matches on every reference colour', () => {
    const bad = rgb.filter((c, i) => rgbToLab8(c[0], c[1], c[2]).join() !== lab[i].join())
    expect(bad).toEqual([])
  })

  it('BGR2GRAY matches on every reference colour', () => {
    const data = new Uint8Array(rgb.length * 4)
    rgb.forEach((c, i) => data.set([c[0], c[1], c[2], 255], 4 * i))
    expect(Array.from(toGray({ width: rgb.length, height: 1, data }))).toEqual(gray)
  })
})

describe('fillPoly (pixel-exact masks)', () => {
  const { width, height, cases: polys } = cases.fillPoly as {
    width: number; height: number; cases: { polygons: Polygon[]; pixels: number[] }[]
  }
  it.each(polys.map((c, i) => [i, c] as const))('case %i', (_, c) => {
    expect(Array.from(maskPixels(fillPolyMask(width, height, c.polygons)))).toEqual(c.pixels)
  })
})

describe('filters', () => {
  it('Gaussian blur matches cv2.GaussianBlur, including kernels wider than the image', () => {
    const { width, height, image, cases: blurs } = cases.blur
    const src = Float64Array.from(image as number[])
    const all = Int32Array.from({ length: width * height }, (_, i) => i)
    for (const b of blurs as { sigma: number; values: number[] }[]) {
      const out = gaussianBlurAt(src, width, height, b.sigma, all)
      const maxErr = Math.max(...b.values.map((v, i) => Math.abs(v - out[i])))
      expect(maxErr, `sigma ${b.sigma}`).toBeLessThan(1e-9)
    }
  })

  it('Laplacian matches cv2.Laplacian(gray, CV_64F)', () => {
    const { width, height, image, values } = cases.laplacian
    const gray = Uint8Array.from(image as number[])
    const out = (values as number[]).map((_, i) => laplacianAt(gray, width, height, i % width, Math.floor(i / width)))
    expect(out).toEqual(values)
  })

  it('reflect101 bounces like OpenCV borderInterpolate', () => {
    expect([-3, -2, -1, 0, 4, 5, 6, 7].map((p) => reflect101(p, 5))).toEqual([3, 2, 1, 0, 4, 3, 2, 1])
    expect(reflect101(-9, 3)).toBe(1)        // several bounces
    expect(reflect101(7, 1)).toBe(0)
  })
})
